import"./chunks/assets.DlmBUlu0.js";import{E as e,at as t,it as n,vt as r}from"./chunks/framework.DwjJr7zi.js";var i=JSON.parse(`{"title":"广东联通免流机制","description":"","frontmatter":{"title":"广东联通免流机制"},"headers":[],"relativePath":"blog/posts/1422.md","filePath":"blog/posts/1422.md","lastUpdated":1784778648000}`),a={name:`blog/posts/1422.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="广东联通免流机制" tabindex="-1">广东联通免流机制 <a class="header-anchor" href="#广东联通免流机制" aria-label="Permalink to “广东联通免流机制”">​</a></h1><img class="telegram-media" src="/telegram/AQADmBVrG1kUCFd9.jpg" alt="Telegram 图片" loading="lazy" decoding="async"><div class="telegram-content"><u>广东联通免流机制</u><br><br>摘自互联网<br><br><blockquote class="telegram-blockquote"><pre class="telegram-blockquote-content">广州机制跟深圳机制，有一个机制混淆基本不免来着。安卓还有苹果手机使用混淆都没免，建议自行查看，4G 网络下深圳机制不友好，至于5G的话没测试过

三位数开头的 IP 有可能能免，比如 123.x.x.x 其他的基本不免 比如 12.x.x.x
具体需要实测

广东联通，看起来像是两家联通公司一样。

一家是广州机制的广东联通公司，一家是深圳机制的。

套餐大同小异，但是在业务，网关上有各有区别，在免流上讲，广州机制的卡容易免流一些。

深圳联通接入，含深圳联通，惠州，东莞，潮汕等地区

广州联通接入，含佛山，肇庆，等地区（欢迎留言补充）

 

广州联通机制，使用定向HOST就可以了，比如现今广泛使用的联通掌厅直播混淆。

深圳联通想要免流，难度比较高，当然也不是不能免：

 

1：深圳联通卡人在深圳：

 

深圳联通很早就限制了WAP网关速率，WAP接入点限速50K，基本没法用。HOST也做了IP白名单，直接HOST很难免流。


动态模式可免，但受限于定向包限量（比如40G限制）。

阿里宝卡，百度圣卡，微博卡，网易卡等含阿里系定向的可使用百度直连动态模式，UC动态直连模式(苹果IOS，安卓都可以用)。

大王卡可用王卡动态（百度圣卡也可以试试王卡动态）

2：深圳联通卡人在外地：

流量情况下手机浏览器直接搜IP，如果IP显示深圳IP，记得找联通人工客服开通拜访地业务并刷新网络。

待IP显示为所在地IP，就可以用归属地的HOST免流了。

 

3：外地联通卡人在深圳：

同样查看IP，如果变成了深圳IP，请联系联通人工客服，要求关闭拜访地业务，刷新网络后查看IP。

待IP显示为卡归属地IP，就可以用归属地免流方式了</pre></blockquote><br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/208/">免流合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">频道资源合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭推荐</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD_A0AAh_-0Fc.webp" alt="🥰" loading="lazy" decoding="async"> #机制 #广州 #深圳 #免流 #联通</div><p class="telegram-source"><a href="https://t.me/zhetengsha/1422">查看 Telegram 原文</a></p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};